import{_ as a,o as t,c as i,a2 as d}from"./chunks/framework.BI_TNnOW.js";const k=JSON.parse('{"title":"Evaluación de condiciones","description":"","frontmatter":{},"headers":[],"relativePath":"content/100-conditions-evaluation.md","filePath":"content/100-conditions-evaluation.md"}'),s={name:"content/100-conditions-evaluation.md"};function o(c,e,n,l,r,h){return t(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="evaluacion-de-condiciones" tabindex="-1">Evaluación de condiciones <a class="header-anchor" href="#evaluacion-de-condiciones" aria-label="Permalink to &quot;Evaluación de condiciones&quot;">​</a></h1><p>En Bash, las condiciones se evalúan utilizando el comando <code>test</code> o la forma equivalente <code>[ ]</code>. Estas herramientas permiten verificar condiciones y controlar el flujo de ejecución en los scripts.</p><h2 id="uso-de" tabindex="-1">Uso de <code>$?</code> <a class="header-anchor" href="#uso-de" aria-label="Permalink to &quot;Uso de `$?`&quot;">​</a></h2><p>El símbolo <code>$?</code> se utiliza en Bash para obtener el código de salida del último comando ejecutado. Este código de salida es:</p><ul><li><code>0</code> si el comando se ejecutó con éxito o la condición es verdadera.</li><li><code>1</code> (o cualquier otro valor distinto de cero) si el comando falló o la condición es falsa.</li></ul><h2 id="uso-de-test-y" tabindex="-1">Uso de <code>test</code> y <code>[]</code> <a class="header-anchor" href="#uso-de-test-y" aria-label="Permalink to &quot;Uso de `test` y `[]`&quot;">​</a></h2><p>El siguiente código ejecutado directamente en el terminal, verifica si <code>10</code> es mayor que <code>20</code> usando <code>test</code>. Como la condición es falsa, el código de salida será <code>1</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -gt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $?</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Salida esperada: 1</span></span></code></pre></div><p>El siguiente código ejecutado directamente en el terminal, evalúa si <code>10</code> es mayor que <code>20</code> utilizando <code>[ ]</code>. Al ser falsa la condición, también devolverá <code>1</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -gt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $?</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Salida esperada: 1</span></span></code></pre></div><p>Este ejemplo utiliza <code>test</code> junto con los operadores <code>&amp;&amp;</code> y <code>||</code> para imprimir &quot;Verdadero&quot; si la condición es cierta, o &quot;Falso&quot; si es falsa:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -gt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Verdadero</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Falso</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Salida esperada: Falso</span></span></code></pre></div><p>Aquí se utiliza <code>[ ]</code> con los mismos operadores para verificar si <code>10</code> es menor que <code>20</code> y devolver el mensaje correspondiente:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -lt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Verdadero</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Falso</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Salida esperada: Verdadero</span></span></code></pre></div><h2 id="operadores-y-evaluaciones-comunes" tabindex="-1">Operadores y evaluaciones comunes <a class="header-anchor" href="#operadores-y-evaluaciones-comunes" aria-label="Permalink to &quot;Operadores y evaluaciones comunes&quot;">​</a></h2><h3 id="comparacion-de-numeros" tabindex="-1">Comparación de números <a class="header-anchor" href="#comparacion-de-numeros" aria-label="Permalink to &quot;Comparación de números&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operador</th><th>Descripción</th><th>Ejemplo</th></tr></thead><tbody><tr><td><code>-eq</code></td><td>Igual a</td><td><code>[ 5 -eq 5 ]</code></td></tr><tr><td><code>-ne</code></td><td>No igual a</td><td><code>[ 5 -ne 3 ]</code></td></tr><tr><td><code>-gt</code></td><td>Mayor que</td><td><code>[ 5 -gt 3 ]</code></td></tr><tr><td><code>-lt</code></td><td>Menor que</td><td><code>[ 3 -lt 5 ]</code></td></tr><tr><td><code>-ge</code></td><td>Mayor o igual que</td><td><code>[ 5 -ge 5 ]</code></td></tr><tr><td><code>-le</code></td><td>Menor o igual que</td><td><code>[ 3 -le 5 ]</code></td></tr></tbody></table><h3 id="comparacion-de-cadenas" tabindex="-1">Comparación de cadenas <a class="header-anchor" href="#comparacion-de-cadenas" aria-label="Permalink to &quot;Comparación de cadenas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operador</th><th>Descripción</th><th>Ejemplo</th></tr></thead><tbody><tr><td><code>=</code></td><td>Igual a</td><td><code>[ &quot;a&quot; = &quot;a&quot; ]</code></td></tr><tr><td><code>!=</code></td><td>No igual a</td><td><code>[ &quot;a&quot; != &quot;b&quot; ]</code></td></tr><tr><td><code>-z</code></td><td>Cadena vacía</td><td><code>[ -z &quot;&quot; ]</code></td></tr><tr><td><code>-n</code></td><td>Cadena no vacía</td><td><code>[ -n &quot;hola&quot; ]</code></td></tr></tbody></table><h3 id="evaluacion-de-archivos" tabindex="-1">Evaluación de archivos <a class="header-anchor" href="#evaluacion-de-archivos" aria-label="Permalink to &quot;Evaluación de archivos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operador</th><th>Descripción</th><th>Ejemplo</th></tr></thead><tbody><tr><td><code>-e</code></td><td>Existe</td><td><code>[ -e archivo ]</code></td></tr><tr><td><code>-f</code></td><td>Es un archivo regular</td><td><code>[ -f archivo ]</code></td></tr><tr><td><code>-d</code></td><td>Es un directorio</td><td><code>[ -d directorio ]</code></td></tr><tr><td><code>-r</code></td><td>Tiene permisos de lectura</td><td><code>[ -r archivo ]</code></td></tr><tr><td><code>-w</code></td><td>Tiene permisos de escritura</td><td><code>[ -w archivo ]</code></td></tr><tr><td><code>-x</code></td><td>Tiene permisos de ejecución</td><td><code>[ -x archivo ]</code></td></tr></tbody></table>',21)])])}const u=a(s,[["render",o]]);export{k as __pageData,u as default};
